solution:
text = input().strip()
last_seen = {}
left = 0
best = 0
for right, ch in enumerate(text):
    if ch in last_seen:
        left = max(left, last_seen[ch] + 1)
    last_seen[ch] = right
    best = max(best, right - left + 1)
print(best)

