# 같은 글자가 다시 나올 때 두 글자 사이 간격의 최솟값을 구해요. (반복되는 글자가 있는 문자열이에요)
text = input().strip()

last_seen = {}
closest = len(text)
for i, ch in enumerate(text):
    if ch in last_seen:
        closest = min(closest, i - last_seen[ch])
    # 글자가 나올 때마다 마지막으로 나온 위치를 새 값으로 덮어 써요.
    last_seen[ch] = i
print(closest)
